#[derive(Clone, Debug, Deserialize, Serialize, PartialEq)]
pub struct Project {
    pub id: String,
    #[serde(default)]
    pub description: String,
    #[serde(default)]
    pub aliases: Vec<String>,
    #[serde(default)]
    pub host: Option<String>,
    #[serde(default)]
    pub cwd: String,
    #[serde(default = "default_runtime")]
    pub runtime: String,
    #[serde(default)]
    pub model: Option<String>,
    #[serde(default = "default_stage_extension")]
    pub stage_extension: bool,
    #[serde(default)]
    pub extra_args: Vec<String>,
    #[serde(default)]
    pub prepare: String,
}

/// Every key a registry entry may carry. Kept beside the struct because serde
/// silently drops anything else, and a dropped key is a project that quietly
/// does the wrong thing.
const PROJECT_FIELDS: [&str; 10] = [
    "id",
    "description",
    "aliases",
    "host",
    "cwd",
    "runtime",
    "model",
    "stage_extension",
    "extra_args",
    "prepare",
];

fn default_runtime() -> String {
    "pi".to_owned()
}
fn default_stage_extension() -> bool {
    true
}

impl Project {
    pub fn is_remote(&self) -> bool {
        self.host.as_ref().is_some_and(|host| !host.is_empty())
    }

    pub fn public(&self) -> serde_json::Value {
        serde_json::json!({
            "id": self.id,
            "description": self.description,
            "aliases": self.aliases,
            "location": format!("{}:{}", self.host.as_deref().unwrap_or("damocles"), self.cwd),
        })
    }
}

