const STAGE_OUTPUT_LIMIT: usize = 64 * 1024;

/// A remote extension copy is provisional until its candidate is adopted.
/// Rollback is explicit because Drop cannot await an SSH cleanup.
pub struct ExtensionStageTxn {
    ssh_program: String,
    host: ValidatedSshTarget,
    path: String,
    committed: bool,
}
impl ExtensionStageTxn {
    pub fn new(ssh_program: impl Into<String>, host: ValidatedSshTarget, path: impl Into<String>) -> Self {
        Self { ssh_program: ssh_program.into(), host, path: path.into(), committed: false }
    }
    pub fn path(&self) -> &str { &self.path }
    pub fn commit(mut self) { self.committed = true; }
    pub async fn rollback(self) -> Result<(), String> {
        if self.committed { return Ok(()); }
        let command = format!("rm -f -- {}", crate::pi_client::shell_quote(&self.path));
        let status = Command::new(&self.ssh_program)
            .args(["-T", "-o", "BatchMode=yes", "-o", "ConnectTimeout=10", self.host.as_str(), &command])
            .status().await.map_err(|error| error.to_string())?;
        status.success().then_some(()).ok_or_else(|| format!("remote cleanup exited with {status}"))
    }
}

